import numpy as np

def l2n(x):
    return x / np.linalg.norm(x, axis=1, keepdims=True)

def log_sigmoid(z):
    return -np.logaddexp(0.0, -z)

def siglip_loss(img, txt, t, b):
    logits = l2n(img) @ l2n(txt).T * t + b
    n = len(img)
    labels = 2 * np.eye(n) - 1            # 대각선 +1, 나머지 -1
    return -np.sum(log_sigmoid(labels * logits)) / n

img = np.array([[1.0, 0.0], [0.0, 1.0]])
txt = np.array([[0.8, 0.6], [0.6, 0.8]])
for b in [0.0, -7.0, -10.0]:
    print(f"b={b:5.1f}  loss={siglip_loss(img, txt, 10.0, b):.4f}")
